insert into public.locations
  (id, name, county, category, latitude, longitude, cost, distance, kicker, description, address, parking, facts)
values
  (73, 'Carrauntoohil', 'Kerry', 'trail', 51.9994496, -9.7426932, 'Free', '12 km return · 5-7 hours', 'Ireland’s highest summit above the MacGillycuddy’s Reeks', 'Follow the Hag’s Glen beneath steep mountain walls before the final climb to Ireland’s 1,039 m summit. This is a serious mountain day: cloud, wind and wet rock can change the character of the route quickly.', 'Cronin’s Yard, Mealis, Beaufort, Co. Kerry', 'Paid parking and facilities at Cronin’s Yard; arrive early on fair-weather weekends.', array['1,039 m summit', 'Strenuous', 'Mountain skills needed']),
  (74, 'Gap of Dunloe', 'Kerry', 'trail', 51.9943895, -9.6442886, 'Free', '11 km through-route', 'A narrow mountain pass threaded between five dark lakes', 'Walk or cycle the old road as it winds between the MacGillycuddy’s Reeks and Purple Mountain, passing stone bridges, glacial lakes and some of Kerry’s grandest close-range mountain scenery.', 'Kate Kearney’s Cottage, Gap of Dunloe, Beaufort, Co. Kerry', 'Limited parking near Kate Kearney’s Cottage; do not obstruct residents or jarvey access.', array['11 km pass', 'Walking & cycling', 'Shared road']),
  (75, 'Slea Head', 'Kerry', 'viewpoint', 52.0980902, -10.455304, 'Free', 'Roadside viewpoints and coastal walks', 'Atlantic cliffs at the far edge of the Dingle Peninsula', 'Look across to the Blasket Islands from a coast of sea cliffs, green headlands and stone-walled fields. The best experience comes from stopping at marked pull-ins and walking short sections away from the road.', 'Slea Head Drive, Dún Chaoin, Co. Kerry', 'Use signed viewing areas only; roadside space is tight in summer.', array['Blasket views', 'Wild Atlantic Way', 'Exposed coast']),
  (76, 'Mizen Head', 'Cork', 'viewpoint', 51.4500965, -9.819755, 'Paid visitor centre', '2 km return to signal station', 'A dramatic signal station above Atlantic sea arches', 'Cross the arched footbridge to the old signal station on Ireland’s south-westerly edge. Clifftop paths reveal deep inlets, offshore rocks and the full force of the Atlantic below.', 'Mizen Head Visitor Centre, Goleen, Co. Cork', 'Large visitor-centre car park; opening and admission vary seasonally.', array['Clifftop bridge', 'Signal station', 'Seasonal hours']),
  (77, 'Barleycove Beach', 'Cork', 'beach', 51.4683950, -9.7764791, 'Free', '2 km strand walk', 'A broad dune-backed beach near Mizen Head', 'A floating footbridge crosses the tidal channel to pale sand and a protected dune system formed after the 1755 Lisbon earthquake. Low tide opens a generous sweep for walking.', 'Barleycove, Goleen, Co. Cork', 'Public parking beside the access road; spaces fill quickly on warm days.', array['Dune system', 'Tidal channel', 'Swimming beach']),
  (78, 'Ballyhoura Forest Trails', 'Limerick', 'trail', 52.319412, -8.506468, 'Free trails · paid parking', '2-51 km routes', 'Forest walking and Ireland’s largest mountain-bike trail network', 'Choose a short nature trail or one of the purpose-built cycling loops climbing through Ballyhoura Forest. Upper sections are exposed, while the trailhead has toilets, showers and a bike wash.', 'Glenosheen Trailhead, Ardpatrick, Co. Limerick', 'Barrier car park at the trailhead; the operator currently charges for parking.', array['Waymarked loops', 'Walking & MTB', 'Trailhead facilities']),
  (79, 'Galtymore', 'Tipperary', 'trail', 52.3660028, -8.1791761, 'Free', '11 km return · 4-5 hours', 'The highest point of the Galtee Mountains', 'Climb from the Black Road to a broad summit with views across the Golden Vale. The upper mountain is open and boggy, with steep ground and little shelter when cloud comes down.', 'Black Road trailhead, Skeheenarinky, Co. Tipperary', 'Small free trailhead car park; park considerately and leave gates clear.', array['919 m summit', 'Strenuous', 'Open mountain']),
  (80, 'Coumshingaun Lough', 'Waterford', 'trail', 52.249754, -7.5222964, 'Free', '7.5 km loop · 4-5 hours', 'A glacial amphitheatre high in the Comeragh Mountains', 'Climb onto the rim above a dark corrie lake for one of Ireland’s most arresting mountain views. The full circuit is steep and exposed; the lower out-and-back still gives a fine view into the coum.', 'Kilclooney Wood car park, Comeragh Mountains, Co. Waterford', 'Small free car park; overflow must not block the narrow road.', array['Corrie lake', 'Steep terrain', 'Navigation required']),
  (81, 'Tramore Beach', 'Waterford', 'beach', 52.152397, -7.1127627, 'Free', '5 km strand', 'A long Atlantic strand beside Tramore’s promenade', 'Walk from the lively promenade towards the quieter dunes and tidal backstrand, with a wide horizon and dependable sea air. Swimming conditions can change, so follow local lifeguard guidance.', 'Tramore Promenade, Co. Waterford', 'Several public car parks serve the promenade; some spaces may be pay and display.', array['5 km strand', 'Promenade access', 'Seasonal lifeguards']),
  (82, 'Hook Head Lighthouse', 'Wexford', 'historic', 52.1237579, -6.9294595, 'Free grounds · paid tour', '1 km headland wander', 'One of the world’s oldest working lighthouses', 'Walk the limestone headland around the striped medieval tower, watching Atlantic swell break across the rocks. Guided tours climb inside the lighthouse; the surrounding coast remains the main spectacle.', 'Hook Lighthouse, Churchtown, Hook Head, Co. Wexford', 'Free on-site visitor parking; check tour times before travelling.', array['800 years old', 'Working lighthouse', 'Coastal geology']),
  (83, 'Raven Point Nature Reserve', 'Wexford', 'trail', 52.3632970, -6.3684344, 'Free', '8 km forest and beach loop', 'Pine woodland meeting the dunes of Curracloe', 'Follow sandy forest tracks through the Raven before returning along a vast strand. The reserve protects an important dune system, so stay on established paths and keep dogs under close control.', 'Raven Wood, Curracloe, Co. Wexford', 'Use the public beach access car parks at Curracloe or Culleton’s Gap.', array['Coastal forest', 'Dune reserve', 'Flat walking']),
  (84, 'Brittas Bay', 'Wicklow', 'beach', 52.8831479, -6.0575796, 'Free beach · seasonal parking charge', '5 km strand', 'Wicklow’s sweeping dune-backed east-coast beach', 'A broad ribbon of sand runs below protected dunes, with room for long walks even on busy days. Boardwalks reduce erosion and give straightforward access from the main car parks.', 'Brittas Bay, Co. Wicklow', 'North and south car parks may charge seasonally; roadside parking is restricted.', array['Blue Flag beach', 'Dune system', 'Boardwalk access']),
  (85, 'Djouce Mountain', 'Wicklow', 'trail', 53.1308589, -6.2399125, 'Free', '8 km return · 3-4 hours', 'A Wicklow summit above the dark waters of Lough Tay', 'Boardwalk and mountain path climb from the Sally Gap road to broad views over Lough Tay, Powerscourt and the Wicklow uplands. Conditions are exposed and the peat surface is fragile off trail.', 'JB Malone car park, Old Military Road, Co. Wicklow', 'Small free car park; alternative access from Ballinastoe is longer.', array['725 m summit', 'Boardwalk sections', 'Exposed ridge']),
  (86, 'Avondale Forest Park', 'Wicklow', 'trail', 52.9133775, -6.2225064, 'Free forest access · paid attractions', '2-5 km trails', 'Mature woodland around the birthplace of Irish forestry', 'Walk beneath giant trees on riverside and estate trails surrounding Avondale House. The forest paths are independent of the ticketed house and treetop attraction.', 'Avondale Forest Park, Rathdrum, Co. Wicklow', 'Large on-site car park; parking or attraction charges may apply.', array['Forest trails', 'Historic estate', 'Treetop walk']),
  (87, 'Dollymount Strand', 'Dublin', 'beach', 53.3669862, -6.1456874, 'Free', '5 km strand', 'A wild-feeling city beach on North Bull Island', 'Walk a long sandy strand with Dublin Bay, Howth and the Poolbeg chimneys on the horizon. The island is an internationally important nature reserve, especially for wintering birds.', 'North Bull Island, Clontarf, Dublin 5', 'Use designated island and causeway parking; restrictions change during busy periods.', array['UNESCO biosphere', 'City beach', 'Bird reserve']),
  (88, 'Newgrange', 'Meath', 'historic', 53.6946974, -6.4755522, 'Paid guided visit', 'Visitor-centre transfer and tour', 'A 5,000-year-old passage tomb aligned to the winter solstice', 'Enter the great kerbed mound as part of a guided Brú na Bóinne visit and see Neolithic art carved into its stones. Access is controlled from the visitor centre, not directly at the monument.', 'Brú na Bóinne Visitor Centre, Donore, Co. Meath', 'Free visitor-centre parking; advance booking is strongly recommended.', array['UNESCO World Heritage', 'c. 3200 BC', 'Guided access']),
  (89, 'Trim Castle', 'Meath', 'historic', 53.5542857, -6.7897751, 'Free grounds · paid keep tour', '1.5 km riverside circuit', 'Ireland’s largest Anglo-Norman castle beside the Boyne', 'Walk around the massive curtain walls and along the river to see the fortress from every angle. A guided ticket gives access to the unusual cruciform keep.', 'Castle Street, Trim, Co. Meath', 'Town car parks and limited on-street spaces nearby; check local restrictions.', array['12th century', 'Riverside walk', 'Guided keep']),
  (90, 'Killykeen Forest Park', 'Cavan', 'trail', 54.0120661, -7.48638, 'Free', '3-8 km loops', 'Woodland trails among the islands of Lough Oughter', 'Easy forest tracks thread between small lakes, mixed woodland and quiet picnic clearings on the Lough Oughter system. It is a gentle place for walking, cycling and watching the water.', 'Killykeen Forest Park, Killeshandra, Co. Cavan', 'Free forest car parks; opening gates and access can vary.', array['Lakeside forest', 'Family trails', 'Picnic areas']),
  (91, 'Clonmacnoise', 'Offaly', 'historic', 53.3263135, -7.9857432, 'Paid visitor site', '1-2 hours', 'A monastic city beside a bend in the Shannon', 'Round towers, high crosses and roofless churches gather on open ground above the river. The setting makes the early medieval site feel connected to the old water routes that sustained it.', 'Clonmacnoise, Shannonbridge, Co. Offaly', 'Free visitor parking included with site access; check seasonal opening.', array['Founded c. 544', 'High crosses', 'Shannon views']),
  (92, 'Ridge of Capard', 'Laois', 'viewpoint', 53.0907048, -7.4898735, 'Free', '2 km loop', 'A boardwalk to wide views from the Slieve Blooms', 'A short woodland climb and boardwalk lead to a high open ridge overlooking the central plain. On a clear day the view reaches far beyond Laois across Ireland’s midlands.', 'Ridge of Capard car park, Slieve Bloom Mountains, Co. Laois', 'Free forest car park at the trailhead.', array['Boardwalk trail', 'Panoramic views', 'Short loop']),
  (93, 'Kilkenny Castle Park', 'Kilkenny', 'historic', 52.6502876, -7.2495286, 'Free park · paid castle', '2 km park circuit', 'A riverside castle and open park in the heart of Kilkenny', 'Approach the great stone façade across sweeping lawns, then follow paths towards the River Nore. The park is free to roam while the restored castle rooms require admission.', 'The Parade, Kilkenny, Co. Kilkenny', 'Use city-centre public car parks; the castle has no visitor parking.', array['Norman origins', 'Free parkland', 'City centre']),
  (94, 'Birr Castle Gardens', 'Offaly', 'historic', 53.095342, -7.91476, 'Paid admission', '2-4 km of garden paths', 'Historic gardens surrounding the Great Telescope', 'Explore mature woodland, formal terraces and lakes around a lived-in castle. The immense Leviathan telescope recalls the estate’s remarkable nineteenth-century scientific work.', 'Birr Castle Demesne, Birr, Co. Offaly', 'Visitor parking near the main entrance; check opening dates and admission.', array['Great Telescope', 'Historic gardens', 'Seasonal opening']),
  (95, 'Portumna Forest Park', 'Galway', 'trail', 53.0816461, -8.2416767, 'Free', '1.5-10 km trails', 'Lakeshore woodland beside Portumna Castle', 'Choose accessible forest paths or longer loops through old oak woodland to the shore of Lough Derg. Red squirrels and fallow deer reward a quiet pace.', 'Portumna Forest Park, Portumna, Co. Galway', 'Free parking at the forest entrance and nearby harbour area.', array['Lough Derg', 'Woodland loops', 'Wildlife watching']),
  (96, 'Dún Aonghasa', 'Galway', 'historic', 53.1254572, -9.7665848, 'Paid visitor site', '2 km return over rough ground', 'A prehistoric stone fort poised above Atlantic cliffs', 'Climb across limestone pavement to concentric stone walls ending abruptly at a sheer cliff edge. There is no barrier at the cliff, and the exposed setting demands care in wind.', 'Kilmurvey, Inis Mór, Aran Islands, Co. Galway', 'Leave bicycles at the visitor area; no private cars are needed on the approach.', array['Prehistoric fort', 'Cliff edge', 'Rough limestone']),
  (97, 'Kylemore Abbey', 'Galway', 'historic', 53.5617436, -9.8894116, 'Paid admission', '2-4 km estate visit', 'A lakeside Victorian castle beneath Connemara mountains', 'The abbey’s pale façade reflects in Pollacapall Lough, backed by steep wooded slopes. Estate paths link the house, Gothic church and walled garden.', 'Kylemore Abbey, Connemara, Co. Galway', 'Large free visitor car park; admission required beyond the entrance.', array['Victorian estate', 'Walled garden', 'Lakeside setting']),
  (98, 'Mullaghmore Loop, Burren National Park', 'Clare', 'trail', 52.996707, -9.0372419, 'Free', '7.5 km loop', 'Terraced limestone and a wild Burren summit', 'A remote route crosses open limestone pavement beside Lough Gealáin before circling Mullaghmore. The rock is rough, waymarking can be subtle and there is little shelter.', 'Gortlecka trailhead, Burren National Park, Co. Clare', 'Small free P1 car park at Gortlecka; never block the narrow road or gates.', array['7.5 km loop', 'Very difficult', 'Limestone pavement']),
  (99, 'Lahinch Beach', 'Clare', 'beach', 52.937279, -9.3560882, 'Free', '2 km strand', 'A broad surf beach facing the Atlantic', 'Walk the promenade and open sand with views south towards the Cliffs of Moher. Swell and currents can be powerful, making local safety advice essential for swimmers.', 'Lahinch Promenade, Co. Clare', 'Town and promenade parking includes paid and time-limited spaces.', array['Surf beach', 'Promenade', 'Atlantic sunsets']),
  (100, 'Enniscrone Beach', 'Sligo', 'beach', 54.209245, -9.1277325, 'Free', '5 km strand', 'Golden sand and dunes at the mouth of Killala Bay', 'A long, open strand curves towards the Ox Mountains, giving ample room for walking and sea views. The dunes are protected, so use signed paths to reach the beach.', 'Enniscrone, Co. Sligo', 'Public beach parking near the pier and main access points.', array['5 km strand', 'Dune system', 'Seasonal lifeguards']),
  (101, 'Knocknarea', 'Sligo', 'trail', 54.2587642, -8.5744955, 'Free', '6 km loop · 2-3 hours', 'Queen Maeve’s cairn above Sligo Bay', 'Climb through woodland and open mountain to a huge unopened passage-tomb cairn. Keep off the cairn itself and take in views over Strandhill, Benbulben and the Atlantic.', 'Queen Maeve Trail, Rathcarrick, Strandhill, Co. Sligo', 'Dedicated trail car park; alternative access from Strandhill is longer.', array['327 m summit', 'Neolithic cairn', 'Coastal panorama']),
  (102, 'Céide Fields', 'Mayo', 'historic', 54.3073032, -9.4581309, 'Paid visitor centre', '1-2 km boardwalk visit', 'A Stone Age field system preserved beneath blanket bog', 'Boardwalks cross an exposed cliff-top landscape where stone walls lay hidden under peat for millennia. The visitor centre explains how farming communities shaped this coast more than 5,000 years ago.', 'Céide Fields, Ballycastle, Co. Mayo', 'Free visitor-centre car park; check seasonal opening.', array['Neolithic landscape', 'Clifftop bog', 'Visitor centre']),
  (103, 'Wild Nephin National Park', 'Mayo', 'trail', 54.0370094, -9.6083412, 'Free', '2-40 km routes', 'Ireland’s largest roadless wilderness', 'Walk forest loops at Letterkeen or commit to remote mountain and bog routes beneath the Nephin Beg range. Longer journeys demand navigation, self-sufficiency and a reliable weather window.', 'Letterkeen trailhead, Newport, Co. Mayo', 'Free trailhead parking; approach roads are narrow and remote.', array['Dark Sky Park', 'Remote wilderness', 'Multiple routes']),
  (104, 'Mulranny Beach', 'Mayo', 'beach', 53.897445, -9.784688, 'Free', '1-3 km shore walk', 'A sheltered strand overlooking the islands of Clew Bay', 'A causeway reaches sand, salt marsh and machair beneath the Nephin Beg mountains. The Great Western Greenway passes through the village just above the shore.', 'Mulranny Beach, Mulranny, Co. Mayo', 'Free public car park near the causeway; spaces are limited in summer.', array['Clew Bay views', 'Greenway access', 'Machair habitat']),
  (105, 'Silver Strand, Malin Beg', 'Donegal', 'beach', 54.6638672, -8.7731391, 'Free', '170 steps to the beach', 'A horseshoe cove enclosed by high Donegal cliffs', 'From the viewing area, a steep staircase descends to pale sand and clear Atlantic water. The climb back is substantial, and tides can reduce the available beach.', 'Malin Beg, Glencolmcille, Co. Donegal', 'Small free cliff-top car park; turning space is limited.', array['Horseshoe cove', '170 steps', 'Cliff-top view']),
  (106, 'Ards Forest Park', 'Donegal', 'trail', 55.15293, -7.90589, 'Free trails · parking charge may apply', '1-13 km loops', 'Woodland, beaches and headlands around Sheephaven Bay', 'Marked trails move from deep forest to salt marsh, dunes and small sandy coves. Few Irish forest parks offer this much coastline within an easy network of loops.', 'Ards Forest Park, Creeslough, Co. Donegal', 'Main forest car park at the N56 entrance; check current barrier charge.', array['Coastal forest', 'Waymarked loops', 'Sheephaven Bay']),
  (107, 'Grianán of Aileach', 'Donegal', 'historic', 55.023832, -7.4274544, 'Free', 'Short walk from car park', 'An ancient ringfort commanding the Inishowen hills', 'Climb through thick circular walls to a parapet view across Lough Swilly, Lough Foyle and the surrounding counties. The exposed hilltop can be windy even on clear days.', 'Grianán of Aileach, Burt, Co. Donegal', 'Free car park below the fort; final access road is narrow.', array['Stone ringfort', 'Hilltop panorama', 'Ancient royal site']),
  (108, 'Marble Arch Caves', 'Fermanagh', 'trail', 54.2585187, -7.8131855, 'Paid cave tour · free trails', '75-minute tour or 3 km gorge walk', 'Underground rivers beneath the Cuilcagh landscape', 'A guided route enters a limestone world of chambers, pools and flowing water. Above ground, the free Cladagh Glen trail follows a wooded gorge towards the cave resurgence.', 'Marble Arch Caves, Florencecourt, Co. Fermanagh', 'Free visitor parking; cave tours should be booked and can be affected by water levels.', array['UNESCO Global Geopark', 'Guided cave', 'Woodland gorge']),
  (109, 'Florence Court', 'Fermanagh', 'historic', 54.2582563, -7.7306108, 'Paid house · estate access varies', '2-9 km estate trails', 'An eighteenth-century house below Cuilcagh Mountain', 'Woodland and mountain-view trails spread around a grand National Trust house, kitchen garden and historic farmyard. The estate is also home to the original Irish yew.', 'Florence Court, Enniskillen, Co. Fermanagh, BT92 1DB', 'National Trust car park; admission and parking arrangements vary by season.', array['Georgian house', 'Estate trails', 'Original Irish yew']),
  (110, 'Beaghmore Stone Circles', 'Tyrone', 'historic', 54.7013563, -6.9389598, 'Free', '1 km boardwalk circuit', 'Bronze Age circles laid out beneath Sperrin skies', 'Boardwalks cross open bog to a complex of low stone circles, alignments and cairns. The isolated setting and broad sky are as memorable as the subtle archaeology.', 'Beaghmore Road, Cookstown, Co. Tyrone', 'Free roadside car park beside the site.', array['Bronze Age', 'Seven circles', 'Dark skies']),
  (111, 'Gortin Glen Forest Park', 'Tyrone', 'trail', 54.6841602, -7.2461194, 'Free', '1-8 km trails', 'Sperrin woodland with a panoramic forest drive', 'Walk signed forest trails or follow the scenic drive to viewpoints over the Owenkillew valley. Play areas and short loops make it accessible without losing the mountain setting.', 'Gortin Glen Forest Park, Omagh, Co. Tyrone', 'Free visitor car parks; scenic-drive gates may close in poor conditions.', array['Sperrin views', 'Forest drive', 'Family trails']),
  (112, 'Navan Fort', 'Armagh', 'historic', 54.347995, -6.6981756, 'Free earthworks · paid visitor centre', '2 km site walk', 'The ceremonial heart of ancient Ulster', 'Walk the great circular enclosure and climb the central mound associated with Emain Macha in Irish mythology. Exhibitions and living-history activities operate from the nearby visitor centre.', 'Navan Centre & Fort, Killylea Road, Armagh, BT60 4LD', 'Free visitor-centre parking; check centre opening and event prices.', array['Ancient Ulster', 'Mythological site', 'Hilltop earthworks']),
  (113, 'Gosford Forest Park', 'Armagh', 'camp', 54.306504, -6.5147344, 'Park entry charge may apply', '2-16 km trails', 'Woodland trails, wildlife and managed camping around Gosford Castle', 'Forest roads and walking loops pass arboretum trees, ponds and glimpses of the castle. A managed campsite and caravan area make this a practical overnight outdoor base rather than wild camping.', 'Gosford Forest Park, Markethill, Co. Armagh', 'On-site parking and managed camping; check current booking and entry arrangements.', array['Managed campsite', 'Forest trails', 'Family cycling']),
  (114, 'Slieve Donard', 'Down', 'trail', 54.1802215, -5.920961, 'Free', '9 km return · 4-5 hours', 'Northern Ireland’s highest summit above Newcastle', 'Climb beside the Glen River through forest before following the Mourne Wall to the 850 m summit. Sea-to-summit views are exceptional, but the upper mountain is steep and exposed.', 'Donard Park, Newcastle, Co. Down', 'Public parking at Donard Park; arrive early on clear weekends.', array['850 m summit', 'Mourne Wall', 'Strenuous']),
  (115, 'Tollymore Forest Park', 'Down', 'camp', 54.2188815, -5.9489858, 'Entry charge may apply', '1-8 km trails', 'River, stone bridges and managed camping beneath the Mournes', 'Trails follow the Shimna River through mature forest, crossing ornate bridges and passing rocky cascades. The established campsite offers a lawful base close to Newcastle and the mountains.', 'Tollymore Forest Park, Bryansford, Co. Down', 'Large on-site car park and bookable managed campsite; check current charges.', array['Managed campsite', 'River trails', 'Mourne views']),
  (116, 'Tyrella Beach', 'Down', 'beach', 54.2517479, -5.7481239, 'Beach access charge may apply', '2 km strand', 'A quiet dune-backed beach facing the Mourne Mountains', 'Wide sand, low dunes and a mountain skyline make Tyrella feel far removed from nearby towns. The beach is managed during the bathing season, with access arrangements varying by date.', 'Tyrella Beach, Downpatrick, Co. Down', 'Managed beach car park; seasonal vehicle access or parking fees may apply.', array['Blue Flag beach', 'Mourne views', 'Dune habitat']),
  (117, 'Scrabo Tower', 'Down', 'viewpoint', 54.5802837, -5.7154558, 'Free grounds', '2 km hill loop', 'A landmark tower above Strangford Lough', 'Climb through Scrabo Country Park to the basalt hilltop and its nineteenth-century tower. The view ranges across Newtownards, the lough’s islands and the Ards Peninsula.', 'Scrabo Country Park, Newtownards, Co. Down', 'Free car park below the tower; interior opening is limited.', array['Strangford panorama', 'Country park', 'Landmark tower']),
  (118, 'Glenariff Forest Park', 'Antrim', 'trail', 55.0194506, -6.124067, 'Free trails · parking charge may apply', '3-9 km trails', 'Waterfalls and deep woodland in the Queen of the Glens', 'The Waterfall Walk descends through a steep-sided glen on timber paths beside the Glenariff River. Longer forest routes climb back to open views towards the sea.', 'Glenariff Forest Park, Glenariff Road, Co. Antrim', 'Main forest car park; check current barrier charge and opening hours.', array['Waterfall walk', 'Steep glen', 'Waymarked trails']),
  (119, 'Carrick-a-Rede', 'Antrim', 'viewpoint', 55.2395381, -6.3324234, 'Paid bridge crossing', '2 km return coastal walk', 'A rope bridge suspended above clear Atlantic water', 'A cliff-top path crosses flower-rich grassland to the famous bridge and views towards Rathlin Island. The coastal walk is rewarding even when bridge tickets are unavailable.', 'Carrick-a-Rede, Ballintoy, Co. Antrim', 'National Trust parking; advance booking may be required for bridge access.', array['Rope bridge', 'Cliff-top path', 'Rathlin views']),
  (120, 'Carrickfergus Castle', 'Antrim', 'historic', 54.7134139, -5.8065062, 'Paid castle entry', '1-2 hour visit', 'A complete Norman fortress guarding Belfast Lough', 'Massive walls and a sea-facing keep tell eight centuries of military history. Walk the harbour outside for the strongest view of the castle reflected against the lough.', 'Marine Highway, Carrickfergus, Co. Antrim, BT38 7BG', 'Public harbour parking beside the castle; check local time limits.', array['Norman castle', 'Harbour setting', 'Eight centuries']),
  (121, 'Benone Strand', 'Derry', 'beach', 55.1807856, -6.9292781, 'Free pedestrian access · vehicle charge may apply', '11 km strand', 'A vast beach beneath Binevenagh and Mussenden Temple', 'One of Ireland’s longest strands runs west towards Magilligan Point, with the cliffs of Binevenagh behind and Donegal across the water. Vehicle access is managed and conditions vary with tides.', 'Benone Strand, Limavady, Co. Derry', 'Use the managed beach and leisure-park entrances; seasonal charges may apply.', array['11 km strand', 'Binevenagh views', 'Managed vehicle access']),
  (122, 'Roe Valley Country Park', 'Derry', 'trail', 55.0213775, -6.9318134, 'Free', '2-7 km riverside trails', 'Wooded riverside paths around historic water-powered mills', 'Follow the River Roe through a steep wooded valley, past rapids, footbridges and industrial remains. Several linked loops allow an easy stroll or a longer circuit.', 'Roe Valley Country Park, Dogleap Road, Limavady, Co. Derry', 'Free car parks at the visitor centre and Dogleap Road entrances.', array['Riverside walks', 'Historic mills', 'Woodland gorge'])
